package com.chainauth.wallet;
import com.chainauth.user.UserRepository;import com.chainauth.wallet.dto.*;import jakarta.servlet.http.HttpServletResponse;import jakarta.validation.Valid;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.security.authentication.AnonymousAuthenticationToken;import org.springframework.web.bind.annotation.*;import java.time.Duration;import java.util.Map;
@RestController@RequestMapping("/api/auth/wallet")public class WalletAuthController{private final WalletAuthService service;private final UserRepository users;private final long days;private final boolean secure;
public WalletAuthController(WalletAuthService s,UserRepository u,@Value("${app.security.refresh-token-days:7}")long d,@Value("${app.security.secure-cookie:false}")boolean c){service=s;users=u;days=d;secure=c;}
@PostMapping("/nonce")public ResponseEntity<?> nonce(@Valid @RequestBody WalletNonceRequest req,Authentication auth){String p=req.purpose()==null?"LOGIN":req.purpose().toUpperCase();String uid=null;if(p.equals("LINK")){if(auth==null||auth instanceof AnonymousAuthenticationToken||!auth.isAuthenticated())return ResponseEntity.status(401).body(Map.of("error","Authentication required"));uid=users.findByEmail(auth.getName()).orElseThrow().getId();}WalletNonce n=service.issueNonce(req.address(),req.chainId(),p,uid);return ResponseEntity.ok(Map.of("message",n.getMessage(),"expiresAt",n.getExpiresAt().toString()));}
@PostMapping("/verify")public ResponseEntity<?> verify(@Valid @RequestBody WalletVerifyRequest req,HttpServletResponse res){var v=service.verify(req,"LOGIN",null);cookie(res,v.session().refreshToken());return ResponseEntity.ok(v.session().response());}
@PostMapping("/link/verify")public ResponseEntity<?> link(@Valid @RequestBody WalletVerifyRequest req,Authentication auth){if(auth==null||auth instanceof AnonymousAuthenticationToken||!auth.isAuthenticated())return ResponseEntity.status(401).body(Map.of("error","Authentication required"));String uid=users.findByEmail(auth.getName()).orElseThrow().getId();var v=service.verify(req,"LINK",uid);return ResponseEntity.ok(Map.of("message","Wallet linked","address",v.address()));}
private void cookie(HttpServletResponse r,String t){ResponseCookie c=ResponseCookie.from("chainauth_refresh",t).httpOnly(true).secure(secure).sameSite("Strict").path("/api/auth").maxAge(Duration.ofDays(days)).build();r.addHeader(HttpHeaders.SET_COOKIE,c.toString());}}
